// 入力: { kind: 'members'|'pcs'|'servers'|'catalog', id?: string }
//   members/pcs/servers … desired(または対象ディレクトリ)と state を両方読み、id で突き合わせて返す
//   catalog            … catalog/ 配下をそのまま返す
// 出力: 1件 = 1エンティティ { id, desired, state, _meta }
//
// 設計: docs/design/03-service-catalog.md(台帳リポジトリ)

const input = $input.first()?.json ?? {};
const kind = input.kind;
const id = input.id ?? null;

const LAYOUT = {
  members: { desired: 'members', state: 'state/members' },
  pcs:     { desired: null,      state: 'state/pcs' },
  servers: { desired: null,      state: 'state/servers' },
  catalog: { desired: 'catalog', state: null },
};

if (!LAYOUT[kind]) {
  throw new Error(`ledger-read: 不正な kind: ${JSON.stringify(kind)}(有効値: ${Object.keys(LAYOUT).join(', ')})`);
}

const repo = $env.LEDGER_REPO;
if (!repo) throw new Error('ledger-read: LEDGER_REPO が未設定です');

const out = [];
for (const [role, dir] of Object.entries(LAYOUT[kind])) {
  if (!dir) continue;
  out.push({ json: { kind, id, role, dir, repo, url: `https://api.github.com/repos/${repo}/contents/${dir}` } });
}
return out;

// ディレクトリ一覧から .yaml だけを取り出し、1ファイル1アイテムにする。
// state ディレクトリが存在しない場合(404)は空として扱う。
const items = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const ctx = $('読み取り対象を決める').all()[i]?.json ?? {};
  const body = item.json;

  // HTTP ノードの continueRegularOutput でエラー時は { error: ... } が入る
  const listing = Array.isArray(body) ? body : (Array.isArray(body?.data) ? body.data : null);
  if (!listing) continue;

  for (const entry of listing) {
    if (entry.type !== 'file' || !entry.name.endsWith('.yaml')) continue;
    const entityId = entry.name.replace(/\.yaml$/, '');
    if (ctx.id && entityId !== ctx.id) continue;
    items.push({ json: {
      kind: ctx.kind,
      role: ctx.role,
      entityId,
      path: entry.path,
      sha: entry.sha,
      url: `https://api.github.com/repos/${ctx.repo}/contents/${entry.path}`,
    }});
  }
}

return items;

// base64 を復号して YAML をパースし、desired と state を entityId で突き合わせる。
// _meta.sha は ledger-write の楽観的排他(競合検出)に使う。
const YAML = require('yaml');

const merged = new Map();

const all = $input.all();
for (let i = 0; i < all.length; i++) {
  const res = all[i].json;
  const ctx = $('YAMLファイルを列挙').all()[i]?.json ?? {};

  const b64 = res.content ?? res.data?.content;
  if (!b64) throw new Error(`ledger-read: ${ctx.path} の内容を取得できませんでした`);

  const text = Buffer.from(b64, 'base64').toString('utf8');
  let parsed;
  try {
    parsed = YAML.parse(text);
  } catch (e) {
    throw new Error(`ledger-read: ${ctx.path} の YAML 解析に失敗: ${e.message}`);
  }

  const key = ctx.entityId;
  if (!merged.has(key)) {
    merged.set(key, { id: key, kind: ctx.kind, desired: null, state: null, _meta: {} });
  }
  const rec = merged.get(key);
  rec[ctx.role] = parsed;
  rec._meta[ctx.role] = { path: ctx.path, sha: res.sha ?? ctx.sha };
}

return [...merged.values()].map((json) => ({ json }));
